        if (사용중(접속번호)) return -98; ئېغىز_قىممىتى[ئايلانما_ئىندېكس] = 접속번호; 묶임[ئايلانما_ئىندېكس] = 1; ھالەت_قىممىتى[ئايلانما_ئىندېكس] = 2; return 0;
