        if (접속번호 < 1 || 접속번호 > 65535 || ھالەت_قىممىتى[ئايلانما_ئىندېكس] > 2) return -22;
        int 수신쪽 = -1; for (int ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش = 0; ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش < 16; ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش++) if (ھالەت_قىممىتى[ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش] == 3 && ئېغىز_قىممىتى[ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش] == 접속번호) 수신쪽 = ئىچكى_قوشۇلما_ئورۇنلاشتۇرۇش;
        if (수신쪽 < 0) return -111;
