    public static int 창구읽기(int 열린파일번호) { int ئايلانما_ئىندېكس = دەلىللىمەك(열린파일번호); return ئايلانما_ئىندېكس < 0 ? -9 : ئېغىز_قىممىتى[ئايلانما_ئىندېكس]; }
