        if (짝[ئايلانما_ئىندېكس] >= 0) 짝[짝[ئايلانما_ئىندېكس]] = -1; ھالەت_قىممىتى[ئايلانما_ئىندېكس] = 묶임[ئايلانما_ئىندېكس] = 수[ئايلانما_ئىندېكس] = 대기[ئايلانما_ئىندېكس] = 0; return 0;
